  prenom: string;
  telephone: string;
  expertise: number;
  disponible: boolean;
  avatar: string;
}

@Component({
  selector: 'app-credit',
  templateUrl: './credit.component.html',
  styleUrls: ['./credit.component.css']
})

export class CreditComponent {

